"""
xarm_manager - 控制器自动切换管理器

功能说明:
1. Topic引导的自动切换: 收到相应的topic时会自动激活相应的controller
2. 超时自动关闭: 如果3秒内没有对应的topic，则相应的控制器自动关闭
3. 冲突自动解决: 控制器切换时自动解决资源冲突
4. 外部强制激活: 通过/xarm_manager/force_controller服务强制激活指定的控制器

设计理念:
- 使用 controller_state_tracker 全局追踪需要激活的控制器
- Topic通过source='topic'标记
- Action相关的切换由xarm_action_manager负责(通过source='action'标记)
- 外部强制激活使用source='external'标记
"""

import rclpy
from rclpy.node import Node
from threading import Thread

from xarm_manager.tools import TopicMonitor, controller_state_tracker, list_controllers, get_active_controllers, \
    check_controller_resource_conflict, switch_controllers
from xarm_manager.topic_config import get_all_topic_configs, topic_controller_map
from std_msgs.msg import String


class XArmManagerNode(Node):
    """
    xarm_manager主节点

    核心工作机制:
    1. 监听所有配置的topic
    2. 当收到topic时，通过controller_state_tracker记录需要激活的控制器
    3. 定时检查topic超时和状态变化，触发控制器切换
    4. 控制器切换时自动解决资源冲突
    """

    def __init__(self):
        super().__init__('xarm_manager')
        self._init_params()
        self._init_topic_monitors()
        self._init_timer()

    def _init_params(self):
        """初始化参数"""
        self.controller_manager_name = '/controller_manager'
        self.declare_parameter('robot_type', 'tianyi2')
        self.robot_type = self.get_parameter('robot_type').get_parameter_value().string_value
        self.get_logger().info(f"xarm_manager robot_type: {self.robot_type}")

    def _init_topic_monitors(self):
        """
        初始化话题监控

        为每个配置的topic创建TopicMonitor和subscription。
        TopicMonitor用于跟踪该topic是否收到消息以及消息时间。
        """
        self.topic_configs = get_all_topic_configs()
        self.monitors = {}
        for topic_name, config in self.topic_configs.items():
            monitor = TopicMonitor(topic_name, config.timeout_sec)
            self.monitors[topic_name] = monitor
            self.create_subscription(
                config.msg_type, topic_name,
                lambda msg, m=monitor: self._topic_callback(msg, m), 10
            )

    def _init_timer(self):
        """
        初始化定时器

        定时器10ms触发一次，用于:
        1. 检查topic是否超时(50ms内没收到消息则认为超时)
        2. 检查controller_state_tracker状态变化
        3. 超过3秒未切换时强制执行切换
        """
        self.timer = self.create_timer(0.01, self.timer_callback)
        self._switch_thread = None
        self._last_switch_time = self.get_clock().now()

    def _topic_callback(self, msg, monitor):
        """
        处理话题消息

        1. 记录消息接收时间
        2. 从tracker中标记对应的controller需要激活(source='topic')
        """
        monitor.last_received_time = self.get_clock().now()
        monitor.last_msg = msg
        if monitor.name in topic_controller_map:
            controller_name = topic_controller_map[monitor.name]
            controller_state_tracker.set_controller_required(controller_name, source='topic')

    def timer_callback(self):
        """
        定时器回调(10ms执行一次)

        检查逻辑:
        1. 遍历所有topic monitor，如果超时(50ms无消息)则清除对应controller需求
        2. 检查tracker状态是否有变化
        3. 如果超过3秒未切换则强制执行切换

        触发切换的条件(满足任一):
        - tracker状态变化
        - 距离上次切换超过3秒
        """
        now = self.get_clock().now()
        is_state_changed = False

        # 检查topic是否超时
        for topic_name, monitor in self.monitors.items():
            if monitor.last_received_time is not None:
                elapsed = (now - monitor.last_received_time).nanoseconds / 1e9
                if elapsed > monitor.timeout_sec and topic_name in topic_controller_map:
                    controller_name = topic_controller_map[topic_name]
                    if controller_state_tracker.is_controller_required(controller_name):
                        self.get_logger().info(f'Topic {topic_name} timed out, clearing {controller_name}')
                        controller_state_tracker.set_controller_unrequired(controller_name)
                        is_state_changed = True

        # 检查tracker状态是否变化
        required_now = set(controller_state_tracker.get_all_required())
        if hasattr(self, '_last_required_controllers') and required_now != self._last_required_controllers:
            is_state_changed = True
            self.get_logger().info(f'Controller state: {self._last_required_controllers} -> {required_now}')
        self._last_required_controllers = required_now

        # 超过3秒未切换则强制执行
        elapsed = (now - self._last_switch_time).nanoseconds / 1e9 if self._last_switch_time else 3.0
        should_switch = is_state_changed or elapsed > 3.0

        if should_switch and (self._switch_thread is None or not self._switch_thread.is_alive()):
            self._switch_thread = Thread(target=self._call_switch_controller, daemon=True)
            self._switch_thread.start()
            self._last_switch_time = now

    def _call_switch_controller(self):
        """
        执行控制器切换

        切换流程:
        1. 获取所有控制器列表和当前激活的控制器
        2. 从tracker获取需要激活的控制器
        3. 过滤不存在的控制器
        4. 检查资源冲突
        5. 计算需要激活和停用的控制器
        6. 调用switch_controller服务

        停用规则:
        - 不在required列表中的已激活控制器(除joint_state_broadcaster外)
        - 与需要激活的控制器有资源冲突的已激活控制器
        """
        try:
            controllers = list_controllers(self, self.controller_manager_name)
            active_controllers = get_active_controllers(controllers)
            required_controllers = controller_state_tracker.get_all_required()

            # 过滤不存在的控制器
            required_controllers = [c for c in required_controllers if c in controllers.keys()]
            if len(required_controllers) != len(controller_state_tracker.get_all_required()):
                missing = set(controller_state_tracker.get_all_required()) - set(required_controllers)
                self.get_logger().error(f"所需控制器未找到: {missing}")

            # 检查required控制器之间的资源冲突
            for i, c1 in enumerate(required_controllers):
                for c2 in required_controllers[i+1:]:
                    if check_controller_resource_conflict(controllers[c1], controllers[c2]):
                        self.get_logger().error(f"控制器冲突: '{c1}' <-> '{c2}'")
                        return

            # 计算需要激活的控制器(尚未激活的)
            require_activate = [c for c in required_controllers if c not in active_controllers]

            # 计算需要停用的控制器
            # 规则: 不在required列表中 且 不是joint_state_broadcaster
            require_deactivate = [name for name, ctrl in active_controllers.items()
                                  if name not in required_controllers and name != 'joint_state_broadcaster']

            # 如果有资源冲突，也需要停用冲突的控制器
            for req in require_activate:
                for name, running in active_controllers.items():
                    if check_controller_resource_conflict(controllers[req], running):
                        require_deactivate.append(name)

            # 执行切换
            if require_activate or require_deactivate:
                self.get_logger().info(f"切换控制器: 关闭{require_deactivate}, 激活{require_activate}")
                switch_controllers(self, self.controller_manager_name, require_deactivate, require_activate, False, False, 10)

        except Exception as e:
            self.get_logger().error(f"switch_controller failed: {e}")
        finally:
            self._switch_thread = None


def main(args=None):
    """主入口"""
    rclpy.init(args=args)
    node = XArmManagerNode()
    node.get_logger().info('xarm_manager node started')
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()
